import random
import string
from typing import List

# This generator targets inputs for FUZZ_PARAM_STR in the sphinx_set_server fuzzer stub,
# which expects a hostname string (DNS name or IPv4/IPv6 literal). The port is generated
# by the fuzzer itself, so we only need to provide interesting host strings. The stub
# falls back to "localhost" if our string is empty; we still include an empty case
# occasionally to exercise that path.
#
# Strategy:
# - Produce a variety of valid host representations:
#   - Common hostnames (localhost, example.com, unicode punycode-like, mixed case)
#   - Subdomains and long labels up to limits
#   - IPv4 addresses, including edge values
#   - IPv6 addresses (compressed, full, with zone index)
#   - Internationalized names (ASCII form); keep overall ASCII to ensure null-terminated C string compatibility
# - Keep total size under 4096 bytes; our strings are short.
# - Deterministic randomness via seed.

MAX_TOTAL = 4096

# Helper builders for different host types

def build_ipv4(r: random.Random) -> str:
    # Ensure valid dotted-quad 0-255 per octet; avoid leading zeros ambiguity by occasionally using them purposely
    def octet():
        mode = r.randrange(3)
        if mode == 0:
            return str(r.randrange(0, 256))
        elif mode == 1:
            # leading zeros variant (still valid as text, though some parsers treat as octal; many libraries accept)
            return f"{r.randrange(0,256):03d}"
        else:
            # edge octets
            return str(r.choice([0, 1, 127, 255]))
    return ".".join(octet() for _ in range(4))

def build_ipv6(r: random.Random) -> str:
    # Build different IPv6 styles
    style = r.randrange(4)
    hexdigits = "0123456789abcdef"

    def group():
        # 1-4 hex chars
        length = r.randint(1, 4)
        return ''.join(r.choice(hexdigits) for _ in range(length))

    if style == 0:
        # Full 8 groups
        return ":".join(f"{r.randrange(0, 65536):x}" for _ in range(8))
    elif style == 1:
        # Compressed :: with some groups left
        left = [group() for _ in range(r.randint(1, 5))]
        right = [group() for _ in range(r.randint(1, 5))]
        return f"{':'.join(left)}::{':'.join(right)}"
    elif style == 2:
        # Loopback / unspecified common forms
        return r.choice(["::1", "::", "2001:db8::1", "fe80::1"])
    else:
        # With zone index (RFC 4007); zone kept simple ascii
        base = "fe80::" + group()
        zone = r.choice(["eth0", "en0", "wlan0", "lo0", str(r.randint(1, 10))])
        return f"{base}%{zone}"

def build_hostname(r: random.Random) -> str:
    # Build a DNS hostname per RFC 1035-ish: labels 1-63, overall <= 253, alnum and hyphen, no leading/trailing '-'
    num_labels = r.randint(1, 5)
    labels: List[str] = []
    for i in range(num_labels):
        # Make some labels special/known
        if i == num_labels - 1 and r.random() < 0.4:
            labels.append(r.choice(["com", "net", "org", "io", "local", "example"]))
            continue
        length = r.randint(1, min(20, 63))
        # Ensure first/last are alnum
        alph = string.ascii_letters + string.digits
        mid_alph = alph + "-"
        if length == 1:
            label = r.choice(alph)
        else:
            middle_len = length - 2
            middle = ''.join(r.choice(mid_alph) for _ in range(middle_len))
            label = r.choice(alph) + middle + r.choice(alph)
        # Occasionally mix case
        if r.random() < 0.3:
            label = ''.join(ch.upper() if r.random() < 0.5 else ch.lower() for ch in label)
        labels.append(label)
    host = ".".join(labels)
    # Occasionally prepend "www" or similar subdomain
    if r.random() < 0.3:
        host = r.choice(["www", "api", "db", "mail"]) + "." + host
    return host

def build_idn_like(r: random.Random) -> str:
    # Simulate an ASCII punycode-like host (not doing real punycode to avoid deps)
    # Keep it valid ASCII with xn-- prefix and mix of alnum/hyphen
    def puny_label():
        core_len = r.randint(3, 20)
        core = ''.join(r.choice(string.ascii_lowercase + string.digits + "-") for _ in range(core_len))
        return "xn--" + core
    labels = [puny_label(), r.choice(["com", "net", "org", "example", "tld"])]
    # Maybe add a subdomain
    if r.random() < 0.5:
        labels.insert(0, build_hostname(r).split('.')[0])
    return ".".join(labels)

def build_special_known(r: random.Random) -> str:
    return r.choice([
        "localhost",
        "example.com",
        "EXAMPLE.com",
        "sub.example.com",
        "intra.local",
        "127.0.0.1",
        "::1",
        "0.0.0.0",
        "255.255.255.255",
        "[::1]",          # sometimes accepted by parsers; include to exercise code paths
        "[2001:db8::1]"
    ])


def pick_host(r: random.Random) -> str:
    choice = r.randrange(8)
    if choice == 0:
        return build_special_known(r)
    if choice == 1:
        return build_ipv4(r)
    if choice == 2:
        return build_ipv6(r)
    if choice == 3:
        return build_hostname(r)
    if choice == 4:
        return build_idn_like(r)
    if choice == 5:
        # Long but valid hostname near limits
        parts = ["a" * r.randint(1, 63) for _ in range(r.randint(2, 5))]
        return ".".join(parts)
    if choice == 6:
        # Mix hostname and numeric TLD-like
        return build_hostname(r) + "." + str(r.randint(0, 999))
    # Occasionally empty to trigger fallback to "localhost" in stub
    return "" if r.random() < 0.5 else "localhost"


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    host = pick_host(r)
    data = host.encode('ascii', errors='ignore')
    if len(data) > MAX_TOTAL:
        data = data[:MAX_TOTAL]
    return data

import random
import string

# Generates ranking expressions compatible with Sphinx SPH_RANK_EXPR
# Ensures bounded recursion and size.

FUNC_ATOMS = [
    "lcs", "bm25", "tf_idf", "field_mask", "exact_hit", "doc_word_count",
    "sum", "min", "max", "avg", "rank_factor", "user_weight", "proximity",
    "word_count", "hit_count", "doc_id", "query_word_count"
]

BINARY_OPS = ["+", "-", "*", "/", "%", "&", "|", "^"]
UNARY_FUNCS = ["log", "sqrt", "abs", "exp", "sin", "cos", "tan"]
COMPARISONS = [">", ">=", "<", "<=", "==", "!="]

ATTR_NAMES = [
    "title_weight", "body_weight", "tag_weight", "date", "rating",
    "views", "likes", "downloads", "category_id", "author_id",
    "price", "stock", "age", "lat", "lon"
]

IDENT_START = string.ascii_lowercase + "_"
IDENT_CONT = IDENT_START + string.ascii_uppercase + string.digits

MAX_DEPTH = 3


def ident(r: random.Random) -> str:
    n = r.randint(1, 12)
    s = r.choice(IDENT_START)
    s += "".join(r.choice(IDENT_CONT) for _ in range(n-1))
    return s


def number(r: random.Random) -> str:
    if r.random() < 0.6:
        return str(r.randint(0, 1_000_000))
    a = r.uniform(0, 1e4)
    if r.random() < 0.2:
        return f"{a:.6e}"
    s = f"{a:.6f}".rstrip("0").rstrip(".")
    return s if s else "0"


def leaf_atom(r: random.Random) -> str:
    # Non-recursive atoms for base cases
    p = r.random()
    if p < 0.35:
        return number(r)
    elif p < 0.6:
        return r.choice(FUNC_ATOMS)
    elif p < 0.85:
        return r.choice(ATTR_NAMES)
    else:
        return ident(r)


def primary_atom(r: random.Random, depth: int) -> str:
    if depth >= MAX_DEPTH:
        return leaf_atom(r)
    p = r.random()
    if p < 0.25:
        return number(r)
    elif p < 0.45:
        return r.choice(FUNC_ATOMS)
    elif p < 0.65:
        return r.choice(ATTR_NAMES)
    elif p < 0.8:
        return ident(r)
    else:
        # parenthesized subexpression with bounded depth
        return f"({expression(r, depth+1)})"


def func_call(r: random.Random, depth: int) -> str:
    if depth >= MAX_DEPTH:
        # fall back to a leaf to avoid recursion
        return leaf_atom(r)
    if r.random() < 0.5:
        fn = r.choice(UNARY_FUNCS)
        return f"{fn}({expression(r, depth+1)})"
    fn = r.choice(["sum", "min", "max", "avg"])
    argc = 1 if depth+1 >= MAX_DEPTH else r.randint(1, 3)
    args = ", ".join(expression(r, depth+1) for _ in range(argc))
    return f"{fn}({args})"


def conditional(r: random.Random, depth: int) -> str:
    if depth >= MAX_DEPTH:
        # degrade to simple arithmetic if too deep
        return f"{leaf_atom(r)} + {leaf_atom(r)}"
    lhs = expression(r, depth+1)
    rhs = expression(r, depth+1)
    op = r.choice(COMPARISONS)
    cond = f"{lhs} {op} {rhs}"
    a = expression(r, depth+1)
    b = expression(r, depth+1)
    return f"if({cond}, {a}, {b})"


def term(r: random.Random, depth: int) -> str:
    head = primary_atom(r, depth) if r.random() < 0.6 else func_call(r, depth)
    nops = 0 if depth >= MAX_DEPTH else r.randint(0, 2 if depth > 1 else 3)
    parts = [head]
    for _ in range(nops):
        op = r.choice(BINARY_OPS)
        rhs = primary_atom(r, depth) if r.random() < 0.6 else func_call(r, depth)
        parts.append(f"{op} {rhs}")
    return " ".join(parts)


def expression(r: random.Random, depth: int = 0) -> str:
    if depth < MAX_DEPTH and r.random() < 0.15:
        return conditional(r, depth)
    parts = [term(r, depth)]
    nops = 0 if depth >= MAX_DEPTH else r.randint(0, 2 if depth > 1 else 3)
    for _ in range(nops):
        op = r.choice(["+", "-"])
        parts.append(f"{op} {term(r, depth)}")
    return " ".join(parts)


def build_expression(r: random.Random, target_len: int) -> str:
    expr = expression(r)
    while len(expr) < target_len and len(expr) < 4000:
        glue = r.choice([" + ", " * ", " - ", " / "])
        frag = expression(r)
        expr += glue + frag
    return expr[:4000]


def interesting_corpus() -> list[str]:
    return [
        "sum(lcs) * user_weight",
        "bm25 + lcs * 100",
        "if(exact_hit > 0, 1000, bm25 + proximity)",
        "avg(title_weight, body_weight) * (bm25 + lcs)",
        "rank_factor + log(1 + views) * user_weight",
        "sum(hit_count) / (1 + word_count)",
        "min(bm25, 100) + max(lcs, 1)",
        "abs(bm25 - avg(lcs, tf_idf))",
        "(bm25 + 2*lcs) / (1 + doc_word_count)",
        "sqrt(bm25) * (user_weight + exact_hit)"
    ]


def pack_inputs(expr: str) -> bytes:
    data = expr.encode('utf-8', errors='ignore')
    if not data or data[-1] != 0:
        data += b"\x00"
    return data[:4096]


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    if r.random() < 0.5:
        expr = r.choice(interesting_corpus())
    else:
        target = r.randint(24, 256)
        expr = build_expression(r, target)
    return pack_inputs(expr)

