def make_query(rng):
    choice = rng.random()
    if choice < 0.35:
        return rng.choice(_QUERY_SAMPLES)
    elif choice < 0.65:
        # Build extended-like query fragments
        terms = []
        for _ in range(rng.randint(1, 4)):
            mode = rng.randint(0, 4)
            if mode == 0:
                terms.append(rand_ascii(rng, 3, 10))
            elif mode == 1:
                terms.append('"' + rand_ascii(rng, 3, 8) + ' ' + rand_ascii(rng, 3, 8) + '"')
            elif mode == 2:
                terms.append('@title ' + rand_ascii(rng, 3, 10))
            elif mode == 3:
                terms.append('@body ' + rand_ascii(rng, 3, 10))
            else:
                terms.append('(' + rand_ascii(rng, 3, 6) + ' | ' + rand_ascii(rng, 3, 6) + ')')
        return ' '.join(terms)
    else:
        return rand_unicode(rng, 2, 20)


def make_index_list(rng):
    choice = rng.random()
    if choice < 0.5:
        return rng.choice(_INDEX_SAMPLES)
    else:
        # produce comma or space separated names
        count = rng.randint(1, 4)
        names = []
        for _ in range(count):
            base = rand_ascii(rng, 3, 8)
            # constrain to index-like tokens (letters/digits/underscores)
            token = ''.join(ch for ch in base if ch.isalnum() or ch == '_')
            if not token:
                token = 'idx' + str(rng.randint(1, 999))
            names.append(token)
        sep = ',' if rng.random() < 0.5 else ' '
        return sep.join(names)


def make_comment(rng):
    # Optional: sometimes empty to allow harness to pass NULL
    if rng.random() < 0.35:
        return ''
    choice = rng.random()
    if choice < 0.5:
        return rng.choice(_COMMENT_SAMPLES)
    elif choice < 0.8:
        return f"run={rng.randint(1, 100000)} tag={rand_ascii(rng, 3, 10)}"
    else:
        return rand_unicode(rng, 1, 25)


def encode_entries(entries):
    # Concatenate strings with NUL terminators so C++ can treat them as C strings when slicing
    # Keep overall size under 4096 bytes
    out = bytearray()
    for s in entries:
        b = s.encode('utf-8', errors='strict')
        out += b + b"\x00"
    # Truncate if needed
    return bytes(out[:4096])


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    query = make_query(rng)
    if not query:
        query = "test"

    index_list = make_index_list(rng)
    if not index_list:
        index_list = "*"

    comment = make_comment(rng)

    return encode_entries([query, index_list, comment])
